/**
 * Jargon Blocklist - Forbidden Technical Terms in User-Facing Copy
 *
 * Every string generated by the UX translation layer is scanned against
 * this list. If any term appears, the copy is rejected. This enforces
 * plain-English communication with non-technical users.
 */

/** Terms that must NEVER appear in user-facing notifications or UI copy */
export const JARGON_BLOCKLIST: readonly string[] = [
    // Security engine internals
    'anomaly score',
    'anomaly detection',
    'reclassification',
    'reclassified',
    'egress',
    'allowlist',
    'blocklist',
    'provenance',
    'attestation',
    'baseline',
    'entropy',
    'payload',
    'parameter',
    'hash chain',
    'hash-chain',

    // Protocol / architecture terms
    'provenance envelope',
    'PE chain',
    'risk score',
    'risk points',
    'friction level',
    'friction escalation',
    'composite score',
    'confidence score',
    'behavioral baseline',
    'classification verification',
    'intent context',
    'intent binding',
    'device attestation',
    'environment attestation',
    'environment integrity',
    'endpoint rule',
    'endpoint policy',

    // Crypto / security jargon
    'SHA-256',
    'sha256',
    'SSRF',
    'HMAC',
    'nonce',
    'cipher',
    'cryptographic',
    'idempotency',
    'mutex',

    // Internal field names
    'anomalyScore',
    'anomaly_score',
    'riskPoints',
    'risk_points',
    'temporalAnomaly',
    'temporal_anomaly',
    'provenanceChain',
    'provenance_chain',
    'endpointRule',
    'endpoint_rule',
    'data_sensitivity',
    'payload_size_bytes',
    'session_velocity',

    // Developer terms that leak into copy
    'null state',
    'null_state',
    'fallback',
    'middleware',
    'serialization',
    'deserialization',
    'webhook',
    'callback',
    'runtime',
] as const;

/**
 * Check if a string contains any jargon from the blocklist.
 *
 * @param text - The text to check
 * @returns Object with `clean` boolean and `violations` array of found terms
 */
export function containsJargon(text: string): {
    clean: boolean;
    violations: string[];
} {
    const lower = text.toLowerCase();
    const violations: string[] = [];

    for (const term of JARGON_BLOCKLIST) {
        if (lower.includes(term.toLowerCase())) {
            violations.push(term);
        }
    }

    return {
        clean: violations.length === 0,
        violations,
    };
}

/**
 * Assert that text is jargon-free. Throws if any violations are found.
 * Used in tests to enforce the blocklist.
 */
export function assertJargonFree(text: string, context?: string): void {
    const result = containsJargon(text);
    if (!result.clean) {
        const prefix = context ? `[${context}] ` : '';
        throw new Error(
            `${prefix}Jargon detected in user-facing copy: ${result.violations.join(', ')}. ` +
            `Text: "${text}"`
        );
    }
}
